import re, subprocess, sys, os

STUBS = r'''
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stddef.h>

typedef unsigned char u8;
typedef unsigned short u16;
typedef unsigned short __le16;
#define __packed __attribute__((packed))
#define GFP_KERNEL 0
#define MWIFIEX_AUTO_IDX_MASK 0xffff
#define MGMT_MASK_BEACON 0x1
#define MGMT_MASK_PROBE_RESP 0x2
#define MGMT_MASK_ASSOC_RESP 0x4
#define IEEE_MAX_IE_SIZE 256
#define WLAN_EID_RSN 48
#define WLAN_EID_VENDOR_SPECIFIC 221
#define WLAN_OUI_MICROSOFT 0x0050f2
#define WLAN_OUI_TYPE_MICROSOFT_WPA 1
#define EINVAL 22
#define ENOMEM 12

struct ieee_types_header { u8 element_id; u8 len; } __packed;

struct mwifiex_ie {
    __le16 ie_index;
    __le16 mgmt_subtype_mask;
    __le16 ie_length;
    u8 ie_buffer[IEEE_MAX_IE_SIZE];
} __packed;

struct cfg80211_beacon_data { const u8 *tail; int tail_len; };
struct mwifiex_private { u16 rsn_idx; u16 gen_idx; };

#define CANARY 0xAB
static unsigned char *g_last;
static size_t g_last_size;
static int g_canary_ok = 1;
static int g_free_count;

static void *kzalloc(size_t n, int f) {
    (void)f;
    unsigned char *p = calloc(1, n + 32);
    memset(p + n, CANARY, 32);
    g_last = p; g_last_size = n; g_canary_ok = 1;
    return p;
}
static void kfree(void *p) {
    if (p == g_last && p) {
        for (size_t i = 0; i < 32; i++) {
            if (g_last[i + g_last_size] != CANARY) { g_canary_ok = 0; break; }
        }
        g_free_count++;
    }
    free(p);
}
static __le16 cpu_to_le16(u16 v) { return v; }

static const u8 *cfg80211_find_ie(u8 eid, const u8 *ies, int len) {
    while (len > 2 && ies[0] != eid) { len -= ies[1] + 2; ies += ies[1] + 2; }
    if (len < 2) return NULL;
    if (len < 2 + ies[1]) return NULL;
    return ies;
}
static const u8 *cfg80211_find_vendor_ie(unsigned int oui, u8 oui_type,
                                         const u8 *ies, int len) {
    const u8 *pos = ies, *end = ies + len;
    while (pos < end) {
        pos = cfg80211_find_ie(WLAN_EID_VENDOR_SPECIFIC, pos, end - pos);
        if (!pos) return NULL;
        u8 ie_len = pos[1];
        if (ie_len < 6) { pos += 2 + ie_len; continue; }
        unsigned int ie_oui = pos[2] << 16 | pos[3] << 8 | pos[4];
        if (ie_oui == oui && pos[5] == oui_type) return pos;
        pos += 2 + ie_len;
    }
    return NULL;
}
static int mwifiex_update_uap_custom_ie(struct mwifiex_private *priv, void *a,
        u16 *b, void *c, void *d, void *e, void *f) {
    (void)priv;(void)a;(void)b;(void)c;(void)d;(void)e;(void)f; return 0;
}
static int mwifiex_set_mgmt_beacon_data_ies(struct mwifiex_private *priv,
                                            struct cfg80211_beacon_data *info) {
    (void)priv;(void)info; return 0;
}
'''

FOOTER = r'''
static void reset(void){ g_last=NULL; g_last_size=0; g_canary_ok=1; g_free_count=0; }

static void put_ie(u8 *buf, int *off, u8 eid, u8 len, const u8 *body) {
    buf[*off] = eid; buf[*off+1] = len; (*off) += 2;
    if (body) memcpy(buf + *off, body, len); (*off) += len;
}

static int run_case(const char *name, const u8 *tail, int tail_len, int expect) {
    struct mwifiex_private priv; memset(&priv, 0, sizeof(priv));
    struct cfg80211_beacon_data info; info.tail = tail; info.tail_len = tail_len;
    reset();
    int rc = mwifiex_set_mgmt_ies(&priv, &info);
    int ok = (rc == expect) && g_canary_ok;
    printf("%-28s rc=%d expect=%d canary_ok=%d frees=%d -> %s\n",
           name, rc, expect, g_canary_ok, g_free_count, ok ? "PASS" : "FAIL");
    return ok;
}

int main(void) {
    u8 body[300];
    int off, all = 1;

    /* Case A positive: RSN len=4 + WPA len=8 -> 6 + 10 = 16 <= 256, rc 0 */
    memset(body, 0x11, sizeof(body));
    u8 tailA[64]; off = 0;
    put_ie(tailA, &off, WLAN_EID_RSN, 4, body);
    u8 wpabody[8]; memset(wpabody, 0, sizeof(wpabody));
    wpabody[0]=0x00; wpabody[1]=0x50; wpabody[2]=0xf2; wpabody[3]=WLAN_OUI_TYPE_MICROSOFT_WPA;
    put_ie(tailA, &off, WLAN_EID_VENDOR_SPECIFIC, 8, wpabody);
    all &= run_case("positive(rsn4+wpa8)", tailA, off, 0);

    /* Case B negative RSN: single RSN len=255, tail_len=257 -> 257 > 256 */
    u8 tailB[257]; off = 0;
    put_ie(tailB, &off, WLAN_EID_RSN, 255, body);
    all &= run_case("negative(rsn255)", tailB, off, -EINVAL);

    /* Case C negative WPA: RSN len=10 (ie_len=12) + WPA len=255 -> 269 > 256 */
    u8 tailC[300]; off = 0;
    put_ie(tailC, &off, WLAN_EID_RSN, 10, body);
    u8 wpabig[255]; memset(wpabig, 0, sizeof(wpabig));
    wpabig[0]=0x00; wpabig[1]=0x50; wpabig[2]=0xf2; wpabig[3]=WLAN_OUI_TYPE_MICROSOFT_WPA;
    put_ie(tailC, &off, WLAN_EID_VENDOR_SPECIFIC, 255, wpabig);
    all &= run_case("negative(rsn10+wpa255)", tailC, off, -EINVAL);

    /* Case D boundary: RSN len=254 -> exactly 256, allowed */
    u8 tailD[257]; off = 0;
    put_ie(tailD, &off, WLAN_EID_RSN, 254, body);
    all &= run_case("boundary(rsn254)", tailD, off, 0);

    /* Case E no tail: succeeds via beacon-data path */
    all &= run_case("no-tail", NULL, 0, 0);

    printf("RESULT: %s\n", all ? "ALL_PASS" : "SOME_FAIL");
    return all ? 0 : 1;
}
'''

def extract_func(path):
    text = open(path, encoding='utf-8', errors='replace').read().splitlines()
    out, started = [], False
    for line in text:
        if not started and re.match(r'int mwifiex_set_mgmt_ies\(', line):
            started = True
        if started:
            out.append(line)
            if line == '}':
                break
    if not out:
        raise SystemExit('function not found in ' + path)
    return "\n".join(out)

def build(src_file, out_c, out_bin):
    func = extract_func(src_file)
    with open(out_c, 'w') as f:
        f.write(STUBS + "\n" + func + "\n" + FOOTER)
    r = subprocess.run(['gcc-8', '-Wall', '-Wextra', '-Wno-unused-parameter',
                        '-o', out_bin, out_c], capture_output=True, text=True)
    return r

if __name__ == '__main__':
    kind = sys.argv[1]
    src = sys.argv[2]
    outdir = sys.argv[3]
    os.makedirs(outdir, exist_ok=True)
    c = os.path.join(outdir, kind + '.c')
    b = os.path.join(outdir, kind + '.bin')
    r = build(src, c, b)
    print("### compile %s: exit=%d" % (kind, r.returncode))
    if r.stderr.strip():
        print(r.stderr.strip()[:4000])
    if r.returncode != 0:
        sys.exit(2)
    run = subprocess.run([b], capture_output=True, text=True)
    print(run.stdout, end='')
    if run.stderr.strip():
        print(run.stderr.strip()[:2000])
    sys.exit(run.returncode)

