} __packed;

struct cfg80211_beacon_data { const u8 *tail; int tail_len; };
struct mwifiex_private { u16 rsn_idx; u16 gen_idx; };

#define CANARY 0xAB
static unsigned char *g_last;
static size_t g_last_size;
static int g_canary_ok = 1;
static int g_free_count;

static void *kzalloc(size_t n, int f) {
    (void)f;
    unsigned char *p = calloc(1, n + 32);
    memset(p + n, CANARY, 32);
    g_last = p; g_last_size = n; g_canary_ok = 1;
    return p;
}
static void kfree(void *p) {
    if (p == g_last && p) {
        size_t i;
        for (i = 0; i < 32; i++) {
            if (g_last[i + g_last_size] != CANARY) { g_canary_ok = 0; break; }
