static void reset(void){ g_last=NULL; g_last_size=0; g_canary_ok=1; g_free_count=0; }

static void put_ie(u8 *buf, int *off, u8 eid, u8 len, const u8 *body) {
    buf[*off] = eid; buf[*off+1] = len; (*off) += 2;
    if (body) memcpy(buf + *off, body, len); (*off) += len;
}

static int run_case(const char *name, const u8 *tail, int tail_len, int expect) {
    struct mwifiex_private priv; memset(&priv, 0, sizeof(priv));
