def extract_func(path):
    text = open(path, encoding='utf-8', errors='replace').read().splitlines()
    out, started = [], False
    for line in text:
        if not started and re.match(r'int mwifiex_set_mgmt_ies\(', line):
            started = True
        if started:
            out.append(line)
            if line == '}':
                break
    if not out:
        raise SystemExit('function not found in ' + path)
    return "\n".join(out)

def build(src_file, out_c, out_bin):
    func = extract_func(src_file)
    with open(out_c, 'w') as f:
        f.write(STUBS + "\n" + func + "\n" + FOOTER)
    return subprocess.run(['gcc-8', '-Wall', '-Wextra', '-Wno-unused-parameter',
                           '-o', out_bin, out_c], capture_output=True, text=True)

if __name__ == '__main__':
    kind = sys.argv[1]
    src = sys.argv[2]
    outdir = sys.argv[3]
    os.makedirs(outdir, exist_ok=True)
    c = os.path.join(outdir, kind + '.c')
    b = os.path.join(outdir, kind + '.bin')
    r = build(src, c, b)
    print("### compile %s: exit=%d" % (kind, r.returncode))
    if r.stderr.strip():
        print(r.stderr.strip()[:4000])
    if r.returncode != 0:
        sys.exit(2)
    run = subprocess.run([b], capture_output=True, text=True)
    print(run.stdout, end='')
    if run.stderr.strip():
        print(run.stderr.strip()[:2000])
    sys.exit(run.returncode)

